#!/bin/bash
# Common utilities for ForgeKit

log_info() {
    echo "[FORGE INFO] $*" >&2
}

log_warn() {
    echo "[FORGE WARN] $*" >&2
}

log_error() {
    echo "[FORGE ERROR] $*" >&2
}

# Get the absolute path to a package directory
get_package_dir() {
    local name="$1"
    echo "$FORGE_ROOT/packages/$name"
}

# Get the absolute path to a package manifest
get_package_manifest() {
    local name="$1"
    echo "$FORGE_ROOT/packages/$name/package.forge"
}

# List all package names (directories under packages/ with a manifest)
list_package_names() {
    local pkg_dir
    for pkg_dir in "$FORGE_ROOT/packages"/*/; do
        if [[ -f "$pkg_dir/package.forge" ]]; then
            basename "$pkg_dir"
        fi
    done
}

# Display formatted package listing
list_packages() {
    local name version type deps
    printf "%-25s %-10s %-10s %s\n" "NAME" "VERSION" "TYPE" "DEPENDENCIES"
    printf "%-25s %-10s %-10s %s\n" "----" "-------" "----" "------------"
    for pkg_name in $(list_package_names); do
        parse_manifest "$pkg_name"
        name="${MANIFEST_name:-$pkg_name}"
        version="${MANIFEST_version:-unknown}"
        type="${MANIFEST_type:-unknown}"
        deps="${MANIFEST_deps:-none}"
        printf "%-25s %-10s %-10s %s\n" "$name" "$version" "$type" "$deps"
    done
}

# Clean build artifacts for a package.  When a profile is supplied, only
# build/<profile>/ is removed and other profiles are left intact.  When no
# profile is supplied, the entire build/ directory is removed, matching the
# existing clean behavior.  Object files associated with the selected scope
# are also removed.
clean_package() {
    local name="$1"
    local profile="${2:-}"
    if [[ -n "$profile" && "$profile" != "debug" && "$profile" != "release" ]]; then
        log_error "Invalid profile: $profile"
        return 1
    fi
    local pkg_dir
    pkg_dir=$(get_package_dir "$name")

    if [[ -z "$profile" ]]; then
        if [[ -d "$pkg_dir/build" ]]; then
            rm -rf "$pkg_dir/build"
            log_info "Cleaned $name (all profiles)"
        fi
        find "$pkg_dir/src" -name "*.o" -delete 2>/dev/null || true
        return 0
    fi

    if [[ -d "$pkg_dir/build/$profile" ]]; then
        rm -rf "$pkg_dir/build/$profile"
        log_info "Cleaned $name ($profile)"
    fi
    if [[ -d "$pkg_dir/build" ]] && [[ -z "$(find "$pkg_dir/build" -mindepth 1 -maxdepth 1 -print -quit 2>/dev/null)" ]]; then
        rmdir "$pkg_dir/build" 2>/dev/null || true
    fi

    # Remove object files for the selected profile.  Makefile builds store
    # objects under build/<profile>; this also handles legacy src-based *.o
    # layouts that encode the profile in the filename or path.
    find "$pkg_dir/src" -name "*.${profile}.o" -delete 2>/dev/null || true
    find "$pkg_dir/src" -path "*/$profile/*" -name "*.o" -delete 2>/dev/null || true
}
